+								ENC_LITTLE_ENDIAN);
+				*offset += 1;
+				len_attr_fields += 1;
+				proto_tree_add_item(p_tree, hf_bios_fail_through_modes, tvb, *offset, 1,
+									ENC_LITTLE_ENDIAN);
